-- Replace sample data with the user's approved 33-item Lebanese menu.
-- Keep UUID primary keys for secure order validation; preserve the supplied numeric menu IDs in menu_number.
begin;
alter table public.categories add column if not exists name_ar text not null default '';
alter table public.menu_items add column if not exists menu_number integer;
alter table public.menu_items add column if not exists category text not null default '';
alter table public.menu_items add column if not exists name_ar text not null default '';
alter table public.menu_items add column if not exists description text not null default '';
alter table public.menu_items add column if not exists ingredients text not null default '';
alter table public.menu_items add column if not exists price_tl integer;
create unique index if not exists menu_items_menu_number_uidx on public.menu_items(menu_number) where menu_number is not null;
update public.categories c set name_en=x.name_en,name_ar=x.name_ar,name_tr=x.name_ar,slug=x.slug from (values
  ('10000000-0000-4000-8000-000000000001'::uuid,'Cold Mezze','مقبلات باردة','01-cold-mezze'),
  ('10000000-0000-4000-8000-000000000002'::uuid,'Salads','سلطات','02-salads'),
  ('10000000-0000-4000-8000-000000000003'::uuid,'Hot Mezze','مقبلات ساخنة','03-hot-mezze'),
  ('10000000-0000-4000-8000-000000000004'::uuid,'Manakish & Breads','مناقيش وخبز','04-manakish-breads'),
  ('10000000-0000-4000-8000-000000000005'::uuid,'Grills','مشاوي','05-grills'),
  ('10000000-0000-4000-8000-000000000006'::uuid,'Main Dishes','أطباق رئيسية','06-main-dishes'),
  ('10000000-0000-4000-8000-000000000007'::uuid,'Desserts','حلويات','07-desserts')
) as x(id,name_en,name_ar,slug) where c.id=x.id;
on conflict (id) do update set menu_number=excluded.menu_number,category=excluded.category,name_en=excluded.name_en,name_ar=excluded.name_ar,description=excluded.description,ingredients=excluded.ingredients,price_tl=excluded.price_tl,image_url=excluded.image_url,category_id=excluded.category_id,name_tr=excluded.name_tr,desc_en=excluded.desc_en,desc_tr=excluded.desc_tr,price=excluded.price,tags=excluded.tags,is_available=excluded.is_available,is_popular=excluded.is_popular;
commit;
